import React, { useState, useEffect } from 'react';

const Ahorro = ({ user }) => {
    const [targetAmount, setTargetAmount] = useState('');
    const [weeklySavings, setWeeklySavings] = useState('');

    useEffect(() => {
        // Solo realizar la petición si user._id está disponible
        if (user && user._id) {
            fetchSavingsData();
        }
    }, [user]);

    const fetchSavingsData = async () => {
        try {
            // Realiza la petición a la API usando el user._id
            const response = await fetch(`http://localhost:5000/api/forms/save/getSave/${user._id}`);
            const result = await response.json();
            
            if (result) {
                // Actualiza los estados con los datos recibidos
                setTargetAmount(result.targetAmount || 'No disponible');
                setWeeklySavings(result.weeklySavings || 'No disponible');
            }
        } catch (error) {
            console.error('Error fetching savings data:', error);
            setTargetAmount('Error al obtener los datos');
            setWeeklySavings('Error al obtener los datos');
        }
    };

    return (
        <div className="ahorro-container">
            <h1 className="ahorro-title">Ahorro</h1>
            <div className="ahorro-content">
                <p><strong>Objetivo:</strong> {targetAmount}</p>
                <p><strong>Cantidad Semanal:</strong> {weeklySavings}</p>
            </div>
        </div>
    );
};

export default Ahorro;
